window.EKT = {"duration":286.9,"groups":[{"id":"title","n":1,"section":1,"title":true,"first":0.05,"end":3.35,"caps":[{"text":"What if everything kept shrinking and couldn't stop?","show":0.05,"hide":3.35,"words":[{"text":"What","start":0.05},{"text":"if","start":0.339},{"text":"everything","start":0.628},{"text":"kept","start":0.916},{"text":"shrinking","start":1.205},{"text":"and","start":1.494},{"text":"couldn't","start":1.782},{"text":"stop?","start":2.071}]}]},{"id":"start","n":2,"section":1,"title":false,"first":4.05,"end":19.3,"caps":[{"text":"6:49 AM, a campsite in the Canadian Rockies. Everything except you just started shrinking.","show":4.05,"hide":9.45,"words":[{"text":"6:49","start":4.05},{"text":"AM,","start":4.32},{"text":"a","start":4.59},{"text":"campsite","start":4.86},{"text":"in","start":5.13},{"text":"the","start":5.4},{"text":"Canadian","start":5.67},{"text":"Rockies.","start":5.94},{"text":"Everything","start":6.21},{"text":"except","start":6.48},{"text":"you","start":6.75},{"text":"just","start":7.02},{"text":"started","start":7.29},{"text":"shrinking.","start":7.56}]},{"text":"Every 30 seconds it halves. And it isn't going to stop.","show":10.35,"hide":14.1,"words":[{"text":"Every","start":10.35},{"text":"30","start":10.589},{"text":"seconds","start":10.827},{"text":"it","start":11.066},{"text":"halves.","start":11.305},{"text":"And","start":11.543},{"text":"it","start":11.782},{"text":"isn't","start":12.02},{"text":"going","start":12.259},{"text":"to","start":12.498},{"text":"stop.","start":12.736}]},{"text":"The tent is closing in. Your son Leo is asleep right beside you.","show":15.1,"hide":19.3,"words":[{"text":"The","start":15.1},{"text":"tent","start":15.326},{"text":"is","start":15.552},{"text":"closing","start":15.778},{"text":"in.","start":16.005},{"text":"Your","start":16.231},{"text":"son","start":16.457},{"text":"Leo","start":16.683},{"text":"is","start":16.909},{"text":"asleep","start":17.135},{"text":"right","start":17.362},{"text":"beside","start":17.588},{"text":"you.","start":17.814}]}]},{"id":"out","n":3,"section":1,"title":false,"first":21.3,"end":29.7,"caps":[{"text":"You push up through the roof.","show":21.3,"hide":23.75,"words":[{"text":"You","start":21.3},{"text":"push","start":21.586},{"text":"up","start":21.872},{"text":"through","start":22.158},{"text":"the","start":22.443},{"text":"roof.","start":22.729}]},{"text":"The whole campsite is shrinking in towards you.","show":26.35,"hide":29.7,"words":[{"text":"The","start":26.35},{"text":"whole","start":26.643},{"text":"campsite","start":26.936},{"text":"is","start":27.229},{"text":"shrinking","start":27.523},{"text":"in","start":27.816},{"text":"towards","start":28.109},{"text":"you.","start":28.402}]}]},{"id":"rule","n":4,"section":1,"title":false,"first":32.3,"end":46.15,"caps":[{"text":"In 1908 the physicist Henri Poincaré asked: if everything changed size overnight, would anyone notice?","show":32.3,"hide":37.7,"words":[{"text":"In","start":32.3},{"text":"1908","start":32.552},{"text":"the","start":32.804},{"text":"physicist","start":33.056},{"text":"Henri","start":33.308},{"text":"Poincaré","start":33.56},{"text":"asked:","start":33.812},{"text":"if","start":34.064},{"text":"everything","start":34.316},{"text":"changed","start":34.568},{"text":"size","start":34.82},{"text":"overnight,","start":35.072},{"text":"would","start":35.324},{"text":"anyone","start":35.576},{"text":"notice?","start":35.828}]},{"text":"His answer: no. Every ruler, and every eye, would change with it.","show":38.7,"hide":42.95,"words":[{"text":"His","start":38.7},{"text":"answer:","start":38.948},{"text":"no.","start":39.196},{"text":"Every","start":39.444},{"text":"ruler,","start":39.692},{"text":"and","start":39.94},{"text":"every","start":40.188},{"text":"eye,","start":40.435},{"text":"would","start":40.683},{"text":"change","start":40.931},{"text":"with","start":41.179},{"text":"it.","start":41.427}]},{"text":"Unless one thing didn't.","show":43.95,"hide":46.15,"words":[{"text":"Unless","start":43.95},{"text":"one","start":44.335},{"text":"thing","start":44.72},{"text":"didn't.","start":45.105}]}]},{"id":"leo","n":5,"section":1,"title":false,"first":48.15,"end":55.55,"caps":[{"text":"Leo climbs out of the tent.","show":48.15,"hide":50.5,"words":[{"text":"Leo","start":48.15},{"text":"climbs","start":48.424},{"text":"out","start":48.698},{"text":"of","start":48.973},{"text":"the","start":49.247},{"text":"tent.","start":49.521}]},{"text":"To him, nothing is shrinking. You're growing.","show":52.3,"hide":55.55,"words":[{"text":"To","start":52.3},{"text":"him,","start":52.625},{"text":"nothing","start":52.95},{"text":"is","start":53.275},{"text":"shrinking.","start":53.6},{"text":"You're","start":53.925},{"text":"growing.","start":54.25}]}]},{"id":"voice","n":6,"section":1,"title":false,"first":56.75,"end":65.75,"caps":[{"text":"He's calling you. Small things ring higher: half the size, an octave up.","show":56.75,"hide":61.35,"words":[{"text":"He's","start":56.75},{"text":"calling","start":56.998},{"text":"you.","start":57.245},{"text":"Small","start":57.493},{"text":"things","start":57.741},{"text":"ring","start":57.988},{"text":"higher:","start":58.236},{"text":"half","start":58.484},{"text":"the","start":58.732},{"text":"size,","start":58.979},{"text":"an","start":59.227},{"text":"octave","start":59.475},{"text":"up.","start":59.722}]},{"text":"His voice is already 2 octaves too high.","show":62.75,"hide":65.75,"words":[{"text":"His","start":62.75},{"text":"voice","start":63.013},{"text":"is","start":63.275},{"text":"already","start":63.538},{"text":"2","start":63.8},{"text":"octaves","start":64.063},{"text":"too","start":64.325},{"text":"high.","start":64.588}]}]},{"id":"weight","n":7,"section":1,"title":false,"first":67.55,"end":83.1,"caps":[{"text":"Half the size, half the pull: a smaller Earth holds you less.","show":67.55,"hide":71.6,"words":[{"text":"Half","start":67.55},{"text":"the","start":67.786},{"text":"size,","start":68.023},{"text":"half","start":68.259},{"text":"the","start":68.495},{"text":"pull:","start":68.731},{"text":"a","start":68.968},{"text":"smaller","start":69.204},{"text":"Earth","start":69.44},{"text":"holds","start":69.676},{"text":"you","start":69.913},{"text":"less.","start":70.149}]},{"text":"You weigh 9 kg. You bend down, and standing back up lifts you off the grass.","show":72.8,"hide":77.6,"words":[{"text":"You","start":72.8},{"text":"weigh","start":73.01},{"text":"9","start":73.22},{"text":"kg.","start":73.43},{"text":"You","start":73.64},{"text":"bend","start":73.85},{"text":"down,","start":74.06},{"text":"and","start":74.27},{"text":"standing","start":74.48},{"text":"back","start":74.69},{"text":"up","start":74.9},{"text":"lifts","start":75.11},{"text":"you","start":75.32},{"text":"off","start":75.53},{"text":"the","start":75.74},{"text":"grass.","start":75.95}]},{"text":"You pick him up. He fits in your hand.","show":80.2,"hide":83.1,"words":[{"text":"You","start":80.2},{"text":"pick","start":80.426},{"text":"him","start":80.651},{"text":"up.","start":80.877},{"text":"He","start":81.102},{"text":"fits","start":81.328},{"text":"in","start":81.553},{"text":"your","start":81.779},{"text":"hand.","start":82.004}]}]},{"id":"neighbours","n":8,"section":2,"title":false,"first":85.5,"end":98.5,"caps":[{"text":"The people at the next campsite are screaming. At you.","show":85.5,"hide":89.2,"words":[{"text":"The","start":85.5},{"text":"people","start":85.759},{"text":"at","start":86.018},{"text":"the","start":86.277},{"text":"next","start":86.536},{"text":"campsite","start":86.795},{"text":"are","start":87.054},{"text":"screaming.","start":87.313},{"text":"At","start":87.572},{"text":"you.","start":87.831}]},{"text":"To them you're 30 metres tall, and growing.","show":90.6,"hide":93.75,"words":[{"text":"To","start":90.6},{"text":"them","start":90.876},{"text":"you're","start":91.151},{"text":"30","start":91.427},{"text":"metres","start":91.703},{"text":"tall,","start":91.978},{"text":"and","start":92.254},{"text":"growing.","start":92.529}]},{"text":"One step could crush them now. You stand still.","show":95.15,"hide":98.5,"words":[{"text":"One","start":95.15},{"text":"step","start":95.411},{"text":"could","start":95.671},{"text":"crush","start":95.932},{"text":"them","start":96.192},{"text":"now.","start":96.453},{"text":"You","start":96.713},{"text":"stand","start":96.974},{"text":"still.","start":97.234}]}]},{"id":"rumble","n":9,"section":2,"title":false,"first":99.9,"end":109.55,"caps":[{"text":"You call out to them. To them, your voice is far too low to hear.","show":99.9,"hide":104.15,"words":[{"text":"You","start":99.9},{"text":"call","start":100.098},{"text":"out","start":100.297},{"text":"to","start":100.495},{"text":"them.","start":100.693},{"text":"To","start":100.892},{"text":"them,","start":101.09},{"text":"your","start":101.288},{"text":"voice","start":101.487},{"text":"is","start":101.685},{"text":"far","start":101.883},{"text":"too","start":102.082},{"text":"low","start":102.28},{"text":"to","start":102.478},{"text":"hear.","start":102.677}]},{"text":"They feel it come up through the ground, like an earthquake.","show":105.55,"hide":109.55,"words":[{"text":"They","start":105.55},{"text":"feel","start":105.805},{"text":"it","start":106.059},{"text":"come","start":106.314},{"text":"up","start":106.568},{"text":"through","start":106.823},{"text":"the","start":107.077},{"text":"ground,","start":107.332},{"text":"like","start":107.586},{"text":"an","start":107.841},{"text":"earthquake.","start":108.095}]}]},{"id":"hush","n":10,"section":2,"title":false,"first":112.15,"end":124.5,"caps":[{"text":"Leo is still calling you. It sounds like a bird now.","show":112.15,"hide":115.75,"words":[{"text":"Leo","start":112.15},{"text":"is","start":112.379},{"text":"still","start":112.608},{"text":"calling","start":112.837},{"text":"you.","start":113.066},{"text":"It","start":113.295},{"text":"sounds","start":113.525},{"text":"like","start":113.754},{"text":"a","start":113.983},{"text":"bird","start":114.212},{"text":"now.","start":114.441}]},{"text":"Then a whistle.","show":117.35,"hide":119.1,"words":[{"text":"Then","start":117.35},{"text":"a","start":117.758},{"text":"whistle.","start":118.167}]},{"text":"Then nothing. His voice is too high for you to hear.","show":120.9,"hide":124.5,"words":[{"text":"Then","start":120.9},{"text":"nothing.","start":121.129},{"text":"His","start":121.358},{"text":"voice","start":121.587},{"text":"is","start":121.816},{"text":"too","start":122.045},{"text":"high","start":122.275},{"text":"for","start":122.504},{"text":"you","start":122.733},{"text":"to","start":122.962},{"text":"hear.","start":123.191}]}]},{"id":"quiet","n":11,"section":2,"title":false,"first":127.5,"end":137.35,"caps":[{"text":"Every sound the valley makes is now too high for you to hear.","show":127.5,"hide":131.55,"words":[{"text":"Every","start":127.5},{"text":"sound","start":127.718},{"text":"the","start":127.936},{"text":"valley","start":128.154},{"text":"makes","start":128.372},{"text":"is","start":128.59},{"text":"now","start":128.808},{"text":"too","start":129.027},{"text":"high","start":129.245},{"text":"for","start":129.463},{"text":"you","start":129.681},{"text":"to","start":129.899},{"text":"hear.","start":130.117}]},{"text":"All you can hear is you.","show":135.15,"hide":137.35,"words":[{"text":"All","start":135.15},{"text":"you","start":135.407},{"text":"can","start":135.663},{"text":"hear","start":135.92},{"text":"is","start":136.177},{"text":"you.","start":136.433}]}]},{"id":"sunrise","n":12,"section":2,"title":false,"first":141.35,"end":146.4,"caps":[{"text":"The Sun is coming up. Up here, you see it first. The valley is still in the dark.","show":141.35,"hide":146.4,"words":[{"text":"The","start":141.35},{"text":"Sun","start":141.546},{"text":"is","start":141.743},{"text":"coming","start":141.939},{"text":"up.","start":142.136},{"text":"Up","start":142.332},{"text":"here,","start":142.528},{"text":"you","start":142.725},{"text":"see","start":142.921},{"text":"it","start":143.118},{"text":"first.","start":143.314},{"text":"The","start":143.51},{"text":"valley","start":143.707},{"text":"is","start":143.903},{"text":"still","start":144.099},{"text":"in","start":144.296},{"text":"the","start":144.492},{"text":"dark.","start":144.689}]}]},{"id":"shadow","n":13,"section":2,"title":false,"first":149.2,"end":158.1,"caps":[{"text":"The peaks across the lake were lit gold.","show":149.2,"hide":152.2,"words":[{"text":"The","start":149.2},{"text":"peaks","start":149.462},{"text":"across","start":149.725},{"text":"the","start":149.987},{"text":"lake","start":150.25},{"text":"were","start":150.513},{"text":"lit","start":150.775},{"text":"gold.","start":151.038}]},{"text":"Now you're blocking their sunrise.","show":155.4,"hide":158.1,"words":[{"text":"Now","start":155.4},{"text":"you're","start":155.778},{"text":"blocking","start":156.156},{"text":"their","start":156.534},{"text":"sunrise.","start":156.912}]}]},{"id":"peaks","n":14,"section":3,"title":false,"first":161.1,"end":169.9,"caps":[{"text":"The lake is a puddle at your feet.","show":161.1,"hide":163.8,"words":[{"text":"The","start":161.1},{"text":"lake","start":161.336},{"text":"is","start":161.573},{"text":"a","start":161.809},{"text":"puddle","start":162.045},{"text":"at","start":162.281},{"text":"your","start":162.517},{"text":"feet.","start":162.754}]},{"text":"The mountains around it are 1,500 metres high. They come up to your waist.","show":165.2,"hide":169.9,"words":[{"text":"The","start":165.2},{"text":"mountains","start":165.435},{"text":"around","start":165.67},{"text":"it","start":165.905},{"text":"are","start":166.14},{"text":"1,500","start":166.375},{"text":"metres","start":166.61},{"text":"high.","start":166.845},{"text":"They","start":167.08},{"text":"come","start":167.315},{"text":"up","start":167.55},{"text":"to","start":167.785},{"text":"your","start":168.02},{"text":"waist.","start":168.255}]}]},{"id":"air","n":15,"section":3,"title":false,"first":172.5,"end":195.1,"caps":[{"text":"To Leo, your hand is now 3 km up. The air there is thin, and 15 degrees below freezing.","show":172.5,"hide":177.85,"words":[{"text":"To","start":172.5},{"text":"Leo,","start":172.697},{"text":"your","start":172.894},{"text":"hand","start":173.091},{"text":"is","start":173.288},{"text":"now","start":173.486},{"text":"3","start":173.683},{"text":"km","start":173.88},{"text":"up.","start":174.077},{"text":"The","start":174.274},{"text":"air","start":174.471},{"text":"there","start":174.668},{"text":"is","start":174.865},{"text":"thin,","start":175.062},{"text":"and","start":175.259},{"text":"15","start":175.457},{"text":"degrees","start":175.654},{"text":"below","start":175.851},{"text":"freezing.","start":176.048}]},{"text":"You have to put him down.","show":179.05,"hide":181.3,"words":[{"text":"You","start":179.05},{"text":"have","start":179.313},{"text":"to","start":179.575},{"text":"put","start":179.838},{"text":"him","start":180.1},{"text":"down.","start":180.363}]},{"text":"You kneel, and put your hand down on the meadow.","show":182.7,"hide":186.1,"words":[{"text":"You","start":182.7},{"text":"kneel,","start":182.938},{"text":"and","start":183.176},{"text":"put","start":183.414},{"text":"your","start":183.652},{"text":"hand","start":183.89},{"text":"down","start":184.128},{"text":"on","start":184.366},{"text":"the","start":184.604},{"text":"meadow.","start":184.842}]},{"text":"Down there, he walks off into the grass.","show":187.7,"hide":190.7,"words":[{"text":"Down","start":187.7},{"text":"there,","start":187.962},{"text":"he","start":188.225},{"text":"walks","start":188.487},{"text":"off","start":188.75},{"text":"into","start":189.013},{"text":"the","start":189.275},{"text":"grass.","start":189.538}]},{"text":"Then you can't see him any more.","show":192.5,"hide":195.1,"words":[{"text":"Then","start":192.5},{"text":"you","start":192.76},{"text":"can't","start":193.02},{"text":"see","start":193.28},{"text":"him","start":193.54},{"text":"any","start":193.8},{"text":"more.","start":194.06}]}]},{"id":"escape","n":16,"section":3,"title":false,"first":196.7,"end":204.6,"caps":[{"text":"You weigh 14 grams. Jump now, and you'd never come back down.","show":196.7,"hide":200.75,"words":[{"text":"You","start":196.7},{"text":"weigh","start":196.936},{"text":"14","start":197.172},{"text":"grams.","start":197.409},{"text":"Jump","start":197.645},{"text":"now,","start":197.881},{"text":"and","start":198.117},{"text":"you'd","start":198.354},{"text":"never","start":198.59},{"text":"come","start":198.826},{"text":"back","start":199.063},{"text":"down.","start":199.299}]},{"text":"You hold on to two mountains.","show":202.15,"hide":204.6,"words":[{"text":"You","start":202.15},{"text":"hold","start":202.436},{"text":"on","start":202.722},{"text":"to","start":203.008},{"text":"two","start":203.293},{"text":"mountains.","start":203.579}]}]},{"id":"plane","n":17,"section":3,"title":false,"first":207.2,"end":211.7,"caps":[{"text":"An airliner, 11 km up, crawls past your face. It's 5 millimetres long.","show":207.2,"hide":211.7,"words":[{"text":"An","start":207.2},{"text":"airliner,","start":207.442},{"text":"11","start":207.685},{"text":"km","start":207.927},{"text":"up,","start":208.169},{"text":"crawls","start":208.412},{"text":"past","start":208.654},{"text":"your","start":208.896},{"text":"face.","start":209.138},{"text":"It's","start":209.381},{"text":"5","start":209.623},{"text":"millimetres","start":209.865},{"text":"long.","start":210.108}]}]},{"id":"curve","n":18,"section":3,"title":false,"first":215.3,"end":219.7,"caps":[{"text":"The whole Earth is 800 metres across now. You can see it curve away.","show":215.3,"hide":219.7,"words":[{"text":"The","start":215.3},{"text":"whole","start":215.52},{"text":"Earth","start":215.74},{"text":"is","start":215.96},{"text":"800","start":216.18},{"text":"metres","start":216.4},{"text":"across","start":216.62},{"text":"now.","start":216.84},{"text":"You","start":217.06},{"text":"can","start":217.28},{"text":"see","start":217.5},{"text":"it","start":217.72},{"text":"curve","start":217.94},{"text":"away.","start":218.16}]}]},{"id":"sky","n":19,"section":3,"title":false,"first":222.7,"end":232.75,"caps":[{"text":"The sky is shrinking too. Its air is all below your eyes.","show":222.7,"hide":226.55,"words":[{"text":"The","start":222.7},{"text":"sky","start":222.925},{"text":"is","start":223.149},{"text":"shrinking","start":223.374},{"text":"too.","start":223.598},{"text":"Its","start":223.823},{"text":"air","start":224.047},{"text":"is","start":224.272},{"text":"all","start":224.497},{"text":"below","start":224.721},{"text":"your","start":224.946},{"text":"eyes.","start":225.17}]},{"text":"Above you: black. And stars, at 6:57 in the morning.","show":229.15,"hide":232.75,"words":[{"text":"Above","start":229.15},{"text":"you:","start":229.402},{"text":"black.","start":229.654},{"text":"And","start":229.906},{"text":"stars,","start":230.158},{"text":"at","start":230.41},{"text":"6:57","start":230.662},{"text":"in","start":230.914},{"text":"the","start":231.166},{"text":"morning.","start":231.418}]}]},{"id":"lift","n":20,"section":4,"title":false,"first":235.75,"end":239.2,"caps":[{"text":"It can barely hold you now. So you hold on to it.","show":235.75,"hide":239.2,"words":[{"text":"It","start":235.75},{"text":"can","start":235.951},{"text":"barely","start":236.153},{"text":"hold","start":236.354},{"text":"you","start":236.555},{"text":"now.","start":236.756},{"text":"So","start":236.958},{"text":"you","start":237.159},{"text":"hold","start":237.36},{"text":"on","start":237.561},{"text":"to","start":237.763},{"text":"it.","start":237.964}]}]},{"id":"moon","n":21,"section":4,"title":false,"first":242.2,"end":247.05,"caps":[{"text":"The Moon is shrinking too, and coming closer. It looks exactly the same size.","show":242.2,"hide":247.05,"words":[{"text":"The","start":242.2},{"text":"Moon","start":242.443},{"text":"is","start":242.685},{"text":"shrinking","start":242.927},{"text":"too,","start":243.17},{"text":"and","start":243.413},{"text":"coming","start":243.655},{"text":"closer.","start":243.897},{"text":"It","start":244.14},{"text":"looks","start":244.383},{"text":"exactly","start":244.625},{"text":"the","start":244.867},{"text":"same","start":245.11},{"text":"size.","start":245.353}]}]},{"id":"house","n":22,"section":4,"title":false,"first":249.45,"end":258.8,"caps":[{"text":"It's the size of a house.","show":249.45,"hide":251.7,"words":[{"text":"It's","start":249.45},{"text":"the","start":249.712},{"text":"size","start":249.975},{"text":"of","start":250.237},{"text":"a","start":250.5},{"text":"house.","start":250.763}]},{"text":"Then a car.","show":253.3,"hide":254.85,"words":[{"text":"Then","start":253.3},{"text":"a","start":253.662},{"text":"car.","start":254.023}]},{"text":"Then it's smaller than you.","show":256.45,"hide":258.8,"words":[{"text":"Then","start":256.45},{"text":"it's","start":256.779},{"text":"smaller","start":257.108},{"text":"than","start":257.437},{"text":"you.","start":257.766}]}]},{"id":"ball","n":23,"section":4,"title":false,"first":261.8,"end":265.8,"caps":[{"text":"It's 30 cm across. Its mass is now 75 kg: the same as yours.","show":261.8,"hide":265.8,"words":[{"text":"It's","start":261.8},{"text":"30","start":262},{"text":"cm","start":262.2},{"text":"across.","start":262.4},{"text":"Its","start":262.6},{"text":"mass","start":262.8},{"text":"is","start":263},{"text":"now","start":263.2},{"text":"75","start":263.4},{"text":"kg:","start":263.6},{"text":"the","start":263.8},{"text":"same","start":264},{"text":"as","start":264.2},{"text":"yours.","start":264.4}]}]},{"id":"end","n":24,"section":4,"title":false,"first":268.4,"end":279.75,"caps":[{"text":"Leo is on it. Everyone is. To them, nothing is shrinking at all.","show":268.4,"hide":272.6,"words":[{"text":"Leo","start":268.4},{"text":"is","start":268.626},{"text":"on","start":268.852},{"text":"it.","start":269.078},{"text":"Everyone","start":269.305},{"text":"is.","start":269.531},{"text":"To","start":269.757},{"text":"them,","start":269.983},{"text":"nothing","start":270.209},{"text":"is","start":270.435},{"text":"shrinking","start":270.662},{"text":"at","start":270.888},{"text":"all.","start":271.114}]},{"text":"In 4 minutes, it'll be a grain of sand. In 10, too small for light to show you.","show":274.8,"hide":279.75,"words":[{"text":"In","start":274.8},{"text":"4","start":274.993},{"text":"minutes,","start":275.185},{"text":"it'll","start":275.378},{"text":"be","start":275.57},{"text":"a","start":275.763},{"text":"grain","start":275.955},{"text":"of","start":276.148},{"text":"sand.","start":276.34},{"text":"In","start":276.533},{"text":"10,","start":276.725},{"text":"too","start":276.918},{"text":"small","start":277.11},{"text":"for","start":277.303},{"text":"light","start":277.495},{"text":"to","start":277.688},{"text":"show","start":277.88},{"text":"you.","start":278.073}]}]},{"id":"question","n":25,"section":4,"title":false,"first":282.35,"end":286.9,"caps":[{"text":"Would you watch it until it's gone?","show":282.35,"hide":286.9,"words":[{"text":"Would","start":282.35},{"text":"you","start":282.625},{"text":"watch","start":282.9},{"text":"it","start":283.175},{"text":"until","start":283.45},{"text":"it's","start":283.725},{"text":"gone?","start":284}]}]}]};
